final class CounterPanel extends JPanel {
    private int count;                       // owned by the component that reads it

    CounterPanel() {
        var button = new JButton("Press");
        button.addActionListener(e -> {
            count++;                         // no static, no global store
            button.setText("pressed " + count + " times");
        });
        add(button);
    }
}
